l(&rp,(1ull<<32)|1ull);ck(cudaMemcpy(f.active,&rp,sizeof(rp),cudaMemcpyHostToDevice),"rootpart");Receipt*d=al<Receipt>();propose_k<<<1,1>>>(f,d);ck(cudaDeviceSynchronize(),"propose");materialize_k<<<1,128>>>(f);ck(cudaDeviceSynchronize(),"materialize");deliver_k<<<1,128>>>(f);ck(cudaDeviceSynchronize(),"deliver");inspect_k<<<1,1>>>(f,d);ck(cudaDeviceSynchronize(),"inspect");DirectBrain brain{};brain.nodes=f.nodes;brain.node_count=2;brain.routes=f.routes;brain.route_capacity=1;brain.route_incarnations=f.inc;brain.boundary_ports=f.ports;brain.boundary_port_count=1;emit_motor_events_kernel<<<1,1>>>(brain,f.nodes,f.routes,f.inc,1,f.ports,nullptr,nullptr,nullptr,0,1,f.egress,f.ehead,f.etail,f.tickets,f.ticket_count,f.ticket_locks,f.actions,f.links,kMaxActionParticipationLinks,f.trajectory,1,nullptr,nullptr,64,f.staging,f.staging_count,16,f.next,2,f.next_inc,f.elig,f.generations,nullptr,f.metrics,101,nullptr,nullptr,nullptr,f.incoming,0);ck(cudaDeviceSynchronize(),"motor");Receipt h{};ck(cudaMemcpy(&h,d,sizeof(h),cudaMemcpyDeviceToHost),"receipt");std::uint32_t tail=0;ck(cudaMemcpy(&tail,f.etail,sizeof(tail),cudaMemcpyDeviceToHost),"tail");MotorEvent ev{};if(tail)ck(cudaMemcpy(&ev,f.egress,sizeof(ev),cudaMemcpyDeviceToHost),"event");DirectActionOccurrence act{};if(tail){std::uint32_t idx=static_cast<std::uint32_t>(ev.ticket_id);idx%=kMaxAsynchronousTickets;ck(cudaMemcpy(&act,f.actions+idx,sizeof(act),cudaMemcpyDeviceToHost),"action");}h.egress=tail>0&&ev.node==1&&ev.channel==20;h.action_pending=h.egress&&act.state==kActionOccurrencePending;h.ancestry_complete=h.egress&&ev.reserved==0;bool green=h.proposed&&h.child&&h.participation&&h.egress&&h.action_pending&&h.ancestry_complete;std::printf("FOUNDRY_DIRECT_CAUSAL_PROGRAM_MOTOR_%s proposed=%u child=%u participation=%u motor_events=%u node=%u channel=%u action_pending=%u ancestry_complete=%u word=%u\n",green?"GREEN":"RED",h.proposed,h.child,h.participation,tail,ev.node,ev.channel,h.action_pending,h.ancestry_complete,ev.word